import gzip,re,os
def load(path):
    b=open(path,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    if b[:3]==b'\xef\xbb\xbf': return b[3:].decode('utf-8')
    if b[:2]==b'\xff\xfe': return b[2:].decode('utf-16-le')
    if b[:2]==b'\xfe\xff': return b[2:].decode('utf-16-be')
    head=b[:2000].decode('latin-1')
    m=re.search(r'^#\s*charset:\s*([^\s]+)',head,re.M)
    enc=m.group(1) if m else 'utf-8'
    return b.decode(enc)
